<?php
require 'config/database.php';$pageTitle='Application Result';$id=(int)($_GET['id']??0);$row=null;
if($id){$stmt=$conn->prepare('SELECT a.application_id,a.status,a.candidate_response,a.application_date,j.title,j.company_name,j.location,j.salary,u.name,u.email,s.phone FROM applications a JOIN jobs j ON j.job_id=a.job_id JOIN users u ON u.user_id=a.seeker_id JOIN job_seekers s ON s.seeker_id=a.seeker_id WHERE a.application_id=?');$stmt->bind_param('i',$id);$stmt->execute();$row=$stmt->get_result()->fetch_assoc();}
include 'includes/header.php';
?>
<section class="result-shell"><div class="page-head"><div><small>CANDIDATE DECISION PORTAL</small><h1>Application Result</h1></div><p>Enter your Application ID to view the live status</p></div><?php if(!$id):?><form class="card result-search" method="get"><h1>Track Your Application</h1><div class="grid"><label class="full">Application ID<input type="number" name="id" placeholder="Example: 1 for APP-000001" required></label></div><button class="submit">Check My Status →</button></form><?php elseif(!$row):?><div class="card result-card"><div class="result-icon rejected">×</div><h2>Application not found</h2><p>Please verify your Application ID and try again.</p><a href="tracking.php">Try again</a></div><?php else:?><div class="card result-card"><span class="reference">APP-<?=str_pad($row['application_id'],6,'0',STR_PAD_LEFT)?></span><?php if($row['status']==='Accepted'):?><div class="result-icon accepted">✓</div><small class="result-label">YOU ARE SELECTED</small><h2>Congratulations, <?=htmlspecialchars($row['name'])?>!</h2><p><strong><?=htmlspecialchars($row['company_name'])?></strong> selected you for the position of <strong><?=htmlspecialchars($row['title'])?></strong>.</p><?php if($row['candidate_response']==='Accepted'):?><div class="response-confirm accepted-response">✓ You accepted this job offer.</div><a class="letter-button" href="appointment_letter.php?id=<?=$row['application_id']?>">Download Appointment Letter →</a><?php elseif($row['candidate_response']==='Declined'):?><div class="response-confirm declined-response">You declined this job offer.</div><?php else:?><div class="offer-box"><strong>Do you want to accept this job offer?</strong><p>The appointment letter becomes available immediately after acceptance.</p><form method="post" action="accept_job.php"><input type="hidden" name="application_id" value="<?=$row['application_id']?>"><button name="decision" value="Accepted" class="accept-offer">✓ Accept Job</button><button name="decision" value="Declined" class="decline-offer">Decline</button></form></div><?php endif;?><?php elseif($row['status']==='Rejected'):?><div class="result-icon rejected">×</div><small class="result-label red">FINAL DECISION</small><h2>Your application was not selected</h2><p>Thank you for applying. You may explore other opportunities from the Application entity.</p><a href="apply.php">Apply for another job</a><?php elseif($row['status']==='Shortlisted'):?><div class="result-icon shortlisted">★</div><small class="result-label amber">SHORTLISTED</small><h2>You reached the next round</h2><p>Your profile is shortlisted. Please wait for the company’s final selection.</p><a href="tracking.php?id=<?=$row['application_id']?>">Refresh Status</a><?php else:?><div class="result-icon pending">⌛</div><small class="result-label gray">UNDER REVIEW</small><h2>Your application is pending</h2><p>The company is reviewing your information. Check this Application ID again later.</p><a href="tracking.php?id=<?=$row['application_id']?>">Refresh Status</a><?php endif;?><div class="result-meta"><span><small>APPLICANT</small><?=htmlspecialchars($row['name'])?></span><span><small>COMPANY & JOB</small><?=htmlspecialchars($row['company_name'])?> · <?=htmlspecialchars($row['title'])?></span><span><small>STATUS</small><?=$row['status']==='Accepted'?'Selected':$row['status']?></span></div></div><?php endif;?></section>
